INSERT INTO public.animal_associations (slug,name,association_type,city,postal_code,departement_code,species,description,needs,siren,rna,legal_form,website_url,facebook_url,instagram_url,donation_url,volunteer_url,contact_page_url,logo_url,tagline,founded_year,key_figures,needs_details,sources,address,verified_at,consent_status,status,internal_note) VALUES
('banque-alimentaire-du-rhone','Banque Alimentaire du Rhône','solidarite','Décines-Charpieu','69150','69','{}'::text[],'La Banque Alimentaire du Rhône collecte des denrées et les distribue gratuitement aux associations et aux centres communaux d''action sociale partenaires, dans le Rhône et la métropole de Lyon. Créée en 1986, elle fait partie de la Fédération Française des Banques Alimentaires. Ses bénévoles préparent les commandes des associations partenaires, conduisent les camions de collecte et mobilisent les habitants lors de la Collecte Nationale, organisée début novembre. Les créneaux de la Collecte Nationale durent une demi-journée, et les missions régulières se poursuivent toute l''année.',ARRAY['benevoles','dons']::text[],'380781138','W691052096','Association déclarée','https://ba69.banquealimentaire.org/','https://www.facebook.com/Banquealimentairedurhone/',NULL,'https://faireundon.banquealimentaire.org/b?cid=2&reserved_ListeBA=BA690&lang=fr_FR','https://ba69.banquealimentaire.org/notre-banque-alimentaire-recherche-35',NULL,'https://ba69.banquealimentaire.org/sites/default/files/styles/local_homepage_logo/public/2022-06/Logo%20BA69_modif.png','Collecte et redistribue des denrées dans le Rhône et la métropole de Lyon, avec des bénévoles toute l''année.',1986,'[{"value": "106", "label": "associations et centres communaux d''action sociale partenaires", "year": "", "source_url": "https://ba69.banquealimentaire.org/"}, {"value": "4 200", "label": "tonnes de denrées distribuées", "year": "", "source_url": "https://ba69.banquealimentaire.org/"}]'::jsonb,'[{"need": "benevoles", "detail": "Missions toute l''année : préparation des commandes pour les associations, conduite de camion, collecte de denrées. La Collecte Nationale revient chaque année début novembre, avec des créneaux d''une demi-journée et une inscription possible en famille.", "url": "https://ba69.banquealimentaire.org/notre-banque-alimentaire-recherche-35"}, {"need": "dons", "detail": "Le don se fait en ligne, directement auprès du réseau des Banques Alimentaires.", "url": "https://faireundon.banquealimentaire.org/b?cid=2&reserved_ListeBA=BA690&lang=fr_FR"}]'::jsonb,'[{"fact": "SIREN 380 781 138, RNA W691052096, association déclarée, siège à Décines-Charpieu (vérifié à l''API officielle le 15/11/2026)", "url": "https://recherche-entreprises.api.gouv.fr/search?q=380781138"}, {"fact": "Activité, missions de bénévolat et chiffres publiés par l''association", "url": "https://ba69.banquealimentaire.org/"}]'::jsonb,NULL,'2026-11-15','pending','published','ASSO-4 vague 1 : SIREN et RNA vérifiés à l''API officielle le 15/11/2026, descriptions rédigées par Guardiens, logo servi depuis le site de l''association.'),
('world-cleanup-day-france','World Cleanup Day France','nature','Lille','59260','59','{}'::text[],'World Cleanup Day France, association nationale basée à Lille, coordonne une mobilisation citoyenne contre les déchets abandonnés : citoyens, associations, écoles, entreprises et collectivités organisent ou rejoignent des ramassages partout en France, notamment à Lyon et à Annecy. L''association équipe aussi des écoles et des événements sportifs ou culturels en outils et en matériel. La journée mondiale a lieu chaque année le 20 septembre : la prochaine édition se tient en septembre 2027, et les inscriptions des organisateurs ouvrent dès le mois de mai.',ARRAY['benevoles','dons']::text[],'828361519','W595029066','Association déclarée','https://www.worldcleanupday.fr/','https://www.facebook.com/worldcleanupdayfrance/','https://www.instagram.com/worldcleanupdayfrance/','https://www.worldcleanupday.fr/adherer-donner/','https://www.worldcleanupday.fr/',NULL,'https://www.worldcleanupday.fr/wp-content/uploads/2025/01/World-Cleanup-Day-FRANCE.webp','La mobilisation citoyenne contre les déchets abandonnés, chaque année autour du 20 septembre, près de chez vous.',2017,'[{"value": "174 250", "label": "participants en moyenne par édition, depuis 2018", "year": "", "source_url": "https://www.worldcleanupday.fr/"}, {"value": "Plus de 31 000", "label": "ramassages de déchets organisés depuis 2018", "year": "", "source_url": "https://www.worldcleanupday.fr/"}]'::jsonb,'[{"need": "benevoles", "detail": "Rejoindre un ramassage sur la carte des événements, en organiser un (inscriptions dès mai) ou devenir ambassadeur ou bénévole. Prochaine journée mondiale : 20 septembre 2027.", "url": "https://www.worldcleanupday.fr/"}, {"need": "dons", "detail": "Faire un don ou adhérer, directement auprès de l''association.", "url": "https://www.worldcleanupday.fr/adherer-donner/"}]'::jsonb,'[{"fact": "SIREN 828 361 519, RNA W595029066, association déclarée, siège à Lille (vérifié à l''API officielle le 15/11/2026)", "url": "https://recherche-entreprises.api.gouv.fr/search?q=828361519"}, {"fact": "Activité, chiffres et prochaine journée mondiale publiés par l''association", "url": "https://www.worldcleanupday.fr/"}]'::jsonb,NULL,'2026-11-15','pending','published','ASSO-4 vague 1 : SIREN et RNA vérifiés à l''API officielle le 15/11/2026, descriptions rédigées par Guardiens, logo servi depuis le site de l''association.'),
('conservatoire-espaces-naturels-isere','Conservatoire d''espaces naturels Isère (CEN Isère)','nature','Saint-Égrève','38120','38','{}'::text[],'Le Conservatoire d''espaces naturels Isère protège et gère des milieux naturels du département, comme les réserves naturelles et les zones humides. Depuis 2024, l''association accueille des bénévoles individuels pour participer à des chantiers nature (par exemple la restauration d''une mare forestière, outils fournis) et à des suivis et inventaires naturalistes. Des groupes locaux de bénévoles se développent autour de ses trois antennes : Saint-Égrève (siège), Le Grand-Lemps et la Platière. Chacun peut aussi partager ses compétences et se former sur le terrain.',ARRAY['benevoles']::text[],'338045776','W381007224','Association déclarée','https://www.cen-isere.org/','https://www.facebook.com/cenisere',NULL,NULL,'https://www.cen-isere.org/benevole/',NULL,'https://www.cen-isere.org/wp-content/uploads/2026/06/LogoCEN38-1-300x159.png','Chantiers nature et suivis naturalistes en Isère, ouverts aux bénévoles depuis 2024.',1986,'[{"value": "40", "label": "ans d''existence du Conservatoire", "year": "2026", "source_url": "https://www.cen-isere.org/benevole/"}, {"value": "3", "label": "antennes, avec des groupes de bénévoles locaux", "year": "", "source_url": "https://www.cen-isere.org/benevole/"}]'::jsonb,'[{"need": "benevoles", "detail": "Chantiers nature, suivis et inventaires naturalistes, groupes locaux de bénévoles. Pour s''inscrire : benevolat@cen-isere.org ou 04 76 48 24 49. L''agenda des chantiers se trouve sur son site.", "url": "https://www.cen-isere.org/benevole/"}]'::jsonb,'[{"fact": "SIREN 338 045 776, RNA W381007224, association déclarée, siège à Saint-Égrève (vérifié à l''API officielle le 15/11/2026)", "url": "https://recherche-entreprises.api.gouv.fr/search?q=338045776"}, {"fact": "Accueil des bénévoles et types de chantiers publiés par l''association", "url": "https://www.cen-isere.org/benevole/"}]'::jsonb,NULL,'2026-11-15','pending','published','ASSO-4 vague 1 : SIREN et RNA vérifiés à l''API officielle le 15/11/2026, descriptions rédigées par Guardiens, logo servi depuis le site de l''association.'),
('compagnons-batisseurs-rhone-alpes','Compagnons Bâtisseurs Rhône-Alpes','chantier','Oullins-Pierre-Bénite','69600','69','{}'::text[],'Présents en Rhône-Alpes depuis 2011, les Compagnons Bâtisseurs aident des familles à améliorer leur logement : accompagnement technique, financier, social et pédagogique, chantiers d''auto-réhabilitation, ateliers de bricolage, outilthèques, chantiers participatifs et Bricobus. L''association intervient dans le Rhône (métropole de Lyon), l''Isère et la Drôme. Les bénévoles prêtent main-forte sur les chantiers solidaires, aux côtés d''un animateur technique, et partagent leur goût du bricolage.',ARRAY['benevoles']::text[],'531814085','W691078022','Association déclarée','https://compagnonsbatisseurs.eu/rhone-alpes','https://www.facebook.com/compagnonsbatisseursRA','https://www.instagram.com/compagnonsbatisseursrhonealpes/',NULL,'https://www.compagnonsbatisseurs.eu/benevolat',NULL,'https://www.compagnonsbatisseurs.eu/assets/img/Logo_simple_C_H_web.png','Chantiers d''auto-réhabilitation et ateliers bricolage pour mieux habiter, dans le Rhône, l''Isère et la Drôme.',2011,'[{"value": "2011", "label": "année d''arrivée de l''association en Rhône-Alpes", "year": "", "source_url": "https://compagnonsbatisseurs.eu/rhone-alpes"}, {"value": "3", "label": "départements d''intervention : Rhône, Isère et Drôme", "year": "", "source_url": "https://compagnonsbatisseurs.eu/rhone-alpes"}]'::jsonb,'[{"need": "benevoles", "detail": "Chantiers solidaires et ateliers de bricolage. Le service civique et le volontariat jeunesse sont aussi possibles. Les modalités se trouvent sur la rubrique Bénévolat de son site.", "url": "https://www.compagnonsbatisseurs.eu/benevolat"}]'::jsonb,'[{"fact": "SIREN 531 814 085, RNA W691078022, association déclarée, siège à Oullins-Pierre-Bénite (vérifié à l''API officielle le 15/11/2026)", "url": "https://recherche-entreprises.api.gouv.fr/search?q=531814085"}, {"fact": "Activité, territoires et rubrique Bénévolat publiés par l''association", "url": "https://compagnonsbatisseurs.eu/rhone-alpes"}]'::jsonb,NULL,'2026-11-15','pending','published','ASSO-4 vague 1 : SIREN et RNA vérifiés à l''API officielle le 15/11/2026, descriptions rédigées par Guardiens, logo servi depuis le site de l''association.'),
('ressourcerie-creative-de-lyon','La Ressourcerie Créative de Lyon','partage','Lyon','69007','69','{}'::text[],'La Ressourcerie Créative de Lyon donne une seconde vie aux objets : boutique associative, ateliers de réparation et de création, location d''objets. Son double objectif : réduire les déchets et créer du lien avec des personnes isolées. Gérée par des bénévoles, elle les accueille ponctuellement ou régulièrement, chacun donnant le temps qu''il souhaite. Les missions : accueil et formation au tri, caisse de la boutique, coordination des bénévoles, communication, co-trésorerie. L''adhésion est de 2 euros par an.',ARRAY['benevoles','dons']::text[],'851790451','W691100109','Association déclarée','https://www.ressourcerielyon.fr/','https://www.facebook.com/RessourcerieCreativeLyon/','https://www.instagram.com/ressourceriecreativelyon/','https://www.ressourcerielyon.fr/dons-a-lassociation-soutenir-la-ressourcerie-creative-de-lyon/','https://www.ressourcerielyon.fr/benevolat/',NULL,'https://www.ressourcerielyon.fr/app/themes/coopi/static/assets/images/Logo_rcl_vf@2x.png','Boutique de réemploi et ateliers à Lyon 7e, portés par des bénévoles qui donnent le temps qu''ils veulent.',2019,'[{"value": "Plus de 170", "label": "bénévoles, dont une cinquantaine actifs chaque semaine", "year": "2024", "source_url": "https://www.labodescreations.fr/blog/bonnes-adresses-15/la-ressourcerie-creative-de-lyon-33"}]'::jsonb,'[{"need": "benevoles", "detail": "Prochaines réunions d''accueil, sans inscription, au 31 rue Pré-Gaudry : mercredi 18 novembre (18 h à 20 h), lundi 30 novembre (18 h à 20 h) et mardi 15 décembre (15 h à 17 h). Il suffit de venir, puis d''adhérer (2 euros par an) et de signer la charte du bénévole.", "url": "https://www.ressourcerielyon.fr/benevolat/"}, {"need": "dons", "detail": "Le don se fait en ligne, sur la page de l''association.", "url": "https://www.ressourcerielyon.fr/dons-a-lassociation-soutenir-la-ressourcerie-creative-de-lyon/"}]'::jsonb,'[{"fact": "SIREN 851 790 451, RNA W691100109, association déclarée, Lyon 7e (vérifié à l''API officielle le 15/11/2026)", "url": "https://recherche-entreprises.api.gouv.fr/search?q=851790451"}, {"fact": "Missions, réunions d''accueil, adhésion et adresse de la boutique publiés par l''association", "url": "https://www.ressourcerielyon.fr/benevolat/"}]'::jsonb,'31 rue Pré-Gaudry','2026-11-15','pending','published','ASSO-4 vague 1 : SIREN et RNA vérifiés à l''API officielle le 15/11/2026, descriptions rédigées par Guardiens, logo servi depuis le site de l''association.'),
('le-passe-jardins','Le Passe-Jardins','partage','Lyon','69008','69','{}'::text[],'Le Passe-Jardins accompagne la création de jardins partagés dans les quartiers et les habitats collectifs, forme les jardiniers et anime un réseau. Le jardin devient le support du lien social, de la transmission des savoirs et de la biodiversité. Fondée en 1998, l''association compte six salariés, plus de 400 jardins partagés accompagnés et 1 600 jardiniers dans son réseau, avec plus de 20 formations et ateliers par an. Les bénévoles sont accueillis à Lyon, en entretien individuel ou lors d''une réunion d''information collective.',ARRAY['benevoles']::text[],'421959875','W691056097','Association déclarée','https://www.lepassejardins.fr/','https://www.facebook.com/lepassejardins/','https://www.instagram.com/lepassejardins/',NULL,NULL,NULL,'https://cdn.prod.website-files.com/6a16f1995127f756228890f8/6a2aa0fc2841cdcc88ab6fac_logo-le-passe-jardins.svg','Le réseau des jardins partagés d''Auvergne-Rhône-Alpes : création, formation et animation depuis 1998.',1998,'[{"value": "400+", "label": "jardins partagés accompagnés", "year": "", "source_url": "https://www.lepassejardins.fr/"}, {"value": "1 600", "label": "jardiniers dans le réseau", "year": "", "source_url": "https://www.lepassejardins.fr/"}, {"value": "20+", "label": "formations et ateliers par an", "year": "", "source_url": "https://www.lepassejardins.fr/"}]'::jsonb,'[{"need": "benevoles", "detail": "Rejoindre le réseau : accueil des bénévoles en entretien individuel ou en réunion d''information collective, puis participation à la vie des jardins. La prise de contact se fait depuis son site.", "url": "https://www.lepassejardins.fr/"}]'::jsonb,'[{"fact": "SIREN 421 959 875, RNA W691056097, association déclarée, Lyon 8e (vérifié à l''API officielle le 15/11/2026)", "url": "https://recherche-entreprises.api.gouv.fr/search?q=421959875"}, {"fact": "Activité et chiffres publiés par l''association", "url": "https://www.lepassejardins.fr/"}]'::jsonb,NULL,'2026-11-15','pending','published','ASSO-4 vague 1 : SIREN et RNA vérifiés à l''API officielle le 15/11/2026, descriptions rédigées par Guardiens, logo servi depuis le site de l''association.'),
('arthropologia','Arthropologia','nature','La Tour-de-Salvagny','69890','69','{}'::text[],'Arthropologia est une association naturaliste fondée en 2001, installée à l''Écocentre du Lyonnais. Elle agit pour la protection du vivant, en particulier des insectes, et pour une autre gestion des espaces de nature. Trois missions : alerter, expliquer, proposer des solutions concrètes. Trois pôles : expertise, formation et mobilisation citoyenne. Le public participe à des sorties, des ateliers, des conférences et des expositions, et contribue aux atlas régionaux des coccinelles et des abeilles d''Auvergne-Rhône-Alpes.',ARRAY['benevoles','participants']::text[],'439602723','W691063966','Association déclarée','https://www.arthropologia.org/',NULL,NULL,NULL,NULL,NULL,'https://www.arthropologia.org/user/themes/arthropologia/build/img/logo.svg','Association naturaliste lyonnaise pour la protection des insectes : sorties, ateliers et sciences participatives.',2001,'[]'::jsonb,'[{"need": "participants", "detail": "Sorties, ateliers, conférences et expositions ouverts au grand public, et contribution aux atlas des coccinelles et des abeilles d''Auvergne-Rhône-Alpes. Le programme se trouve sur son site.", "url": "https://www.arthropologia.org/"}, {"need": "benevoles", "detail": "Ateliers et sorties nature avec des bénévoles : la rubrique Agir avec Arthropologia de son site présente les façons de participer.", "url": "https://www.arthropologia.org/"}]'::jsonb,'[{"fact": "SIREN 439 602 723, RNA W691063966, association déclarée, La Tour-de-Salvagny (vérifié à l''API officielle le 15/11/2026)", "url": "https://recherche-entreprises.api.gouv.fr/search?q=439602723"}, {"fact": "Activité et façons de participer publiées par l''association", "url": "https://www.arthropologia.org/"}]'::jsonb,NULL,'2026-11-15','pending','published','ASSO-4 vague 1 : SIREN et RNA vérifiés à l''API officielle le 15/11/2026, descriptions rédigées par Guardiens, logo servi depuis le site de l''association.'),
('mountain-riders','Mountain Riders','nature','Chambéry','73000','73','{}'::text[],'Mountain Riders est une association d''éducation à la transition écologique en montagne, fondée en 2001 et basée à Chambéry. Son programme Montagne Zéro Déchet vise zéro déchet sauvage en montagne en 2030 : des journées de ramassage ouvertes au public ont lieu dans les stations tout au long de la saison. Les bénévoles s''investissent aussi dans des événements et des stands, la cartographie, la photo, la vidéo, la traduction ou les compétences juridiques, sur le terrain ou à distance. Une visio de bienvenue a lieu chaque trimestre.',ARRAY['benevoles','dons']::text[],'484629837','W691067989','Association déclarée','https://www.mountain-riders.org/','https://www.facebook.com/MountainRidersFrance','https://www.instagram.com/association_mountain_riders/','https://www.mountain-riders.org/soutenez-mountain-riders/','https://www.mountain-riders.org/je-deviens-benevoles/',NULL,NULL,'Éducation à la transition écologique en montagne : ramassages Montagne Zéro Déchet ouverts au public.',2001,'[{"value": "89", "label": "ramassages organisés", "year": "2025", "source_url": "https://www.ici.fr/emissions/l-invite-d-ici-matin-ici-pays-de-savoie/en-deux-ans-la-quantite-de-dechets-ramasses-en-montagne-a-diminue-de-7-6-selon-l-association-mountain-riders-7455167"}]'::jsonb,'[{"need": "benevoles", "detail": "Après l''adhésion : communauté WhatsApp des bénévoles, missions partagées au fil de l''année (ramassages, événements, stands, cartographie, photo, vidéo, traduction) et visio de bienvenue chaque trimestre (date dans l''agenda du site).", "url": "https://www.mountain-riders.org/je-deviens-benevoles/"}, {"need": "dons", "detail": "Le don se fait en ligne, sur la page de l''association.", "url": "https://www.mountain-riders.org/soutenez-mountain-riders/"}]'::jsonb,'[{"fact": "SIREN 484 629 837, RNA W691067989, association déclarée, siège à Chambéry (vérifié à l''API officielle le 15/11/2026)", "url": "https://recherche-entreprises.api.gouv.fr/search?q=484629837"}, {"fact": "Accueil des bénévoles publié par l''association", "url": "https://www.mountain-riders.org/je-deviens-benevoles/"}]'::jsonb,NULL,'2026-11-15','pending','published','ASSO-4 vague 1 : SIREN et RNA vérifiés à l''API officielle le 15/11/2026, descriptions rédigées par Guardiens, logo servi depuis le site de l''association.'),
('club-alpin-francais-lyon-villeurbanne','Club Alpin Français de Lyon-Villeurbanne','randonnee','Villeurbanne','69100','69','{}'::text[],'Le Club Alpin Français de Lyon-Villeurbanne, club de la fédération FFCAM, propose des sorties de montagne encadrées par des bénévoles : randonnée, marche nordique, raquettes, trail, VTT, escalade, via ferrata, canyon, ski de randonnée et alpinisme, des Monts du Lyonnais au Pilat et aux Alpes. Les sorties à la journée sont gratuites, et les sorties de plusieurs jours demandent une participation de 3 à 10 euros par jour selon l''activité. Un non-adhérent peut essayer le club avec la carte découverte, valable pour 3 jours de sorties au maximum.',ARRAY['participants']::text[],'819696535','W691054780','Association déclarée','https://www.clubalpinlyon.fr/','https://fr-fr.facebook.com/pages/Club-Alpin-Fran%C3%A7ais-de-Lyon-Villeurbanne/118851941629324','https://www.instagram.com/clubalpinlyonvilleurbanne/',NULL,NULL,NULL,'https://www.clubalpinlyon.fr/ftp/images/logo.png','Randonnée, escalade, ski de randonnée et alpinisme avec des encadrants bénévoles, carte découverte de 3 jours.',NULL,'[{"value": "3", "label": "jours de sorties avec la carte découverte, avant d''adhérer", "year": "", "source_url": "https://www.clubalpinlyon.fr/pages/organisation-sorties.html"}]'::jsonb,'[{"need": "participants", "detail": "Pour essayer : la carte découverte donne accès à 3 jours de sorties avant l''adhésion. L''inscription se fait en ligne sur le site du club, et l''encadrant valide chaque demande. Condition physique et équipement adaptés au niveau de la sortie.", "url": "https://www.clubalpinlyon.fr/pages/organisation-sorties.html"}]'::jsonb,'[{"fact": "SIREN 819 696 535, RNA W691054780, association déclarée, Villeurbanne (vérifié à l''API officielle le 15/11/2026)", "url": "https://recherche-entreprises.api.gouv.fr/search?q=819696535"}, {"fact": "Organisation des sorties, tarifs et carte découverte publiés par le club", "url": "https://www.clubalpinlyon.fr/pages/organisation-sorties.html"}]'::jsonb,NULL,'2026-11-15','pending','published','ASSO-4 vague 1 : SIREN et RNA vérifiés à l''API officielle le 15/11/2026, descriptions rédigées par Guardiens, logo servi depuis le site de l''association.'),
('espace-nature-isere','Espace Nature Isère','nature','L''Albenc','38470','38','{}'::text[],'Espace Nature Isère agit pour la protection de l''environnement dans le Sud-Grésivaudan depuis plus de 40 ans. Quatre commissions : animations nature, jardin pédagogique, veille écologique (inventaires, suivis naturalistes, diagnostics) et festival. La grande foire écologique L''Avenir au Naturel a tenu sa 30e édition les 5 et 6 septembre 2026, avec plus de 150 exposants et 6 000 visiteurs chaque année. L''association réunit plus de 100 adhérents, 60 bénévoles et 2 salariés, et coordonne des chantiers écologiques avec des jeunes en service civique.',ARRAY['benevoles','dons']::text[],'411545007','W381001816','Association déclarée','https://enisere.fr/','https://www.facebook.com/enisere/','https://www.instagram.com/espacenatureisere/','https://www.helloasso.com/associations/espace-nature-isere/formulaires/7','https://enisere.fr/nous-rejoindre/',NULL,'https://enisere.fr/wp-content/themes/yootheme/cache/f9/espace-nature-isere-logo-texte-a-droite-f96eba65.png','Protection de la nature dans le Sud-Grésivaudan : chantiers écologiques, animations et festival L''Avenir au Naturel.',NULL,'[{"value": "6 000", "label": "visiteurs chaque année au festival L''Avenir au Naturel", "year": "", "source_url": "https://enisere.fr/"}, {"value": "60", "label": "bénévoles", "year": "", "source_url": "https://enisere.fr/"}]'::jsonb,'[{"need": "benevoles", "detail": "Bénévoles bienvenus toute l''année : la préparation du festival commence un an à l''avance (contact : festival@enisere.fr) et les chantiers écologiques se coordonnent avec l''association. Les détails se trouvent sur la page Nous rejoindre.", "url": "https://enisere.fr/nous-rejoindre/"}, {"need": "dons", "detail": "Le don se fait en ligne, sur la page de l''association.", "url": "https://www.helloasso.com/associations/espace-nature-isere/formulaires/7"}]'::jsonb,'[{"fact": "SIREN 411 545 007, RNA W381001816, association déclarée, L''Albenc (vérifié à l''API officielle le 15/11/2026)", "url": "https://recherche-entreprises.api.gouv.fr/search?q=411545007"}, {"fact": "Activité, festival et chiffres publiés par l''association", "url": "https://enisere.fr/"}]'::jsonb,NULL,'2026-11-15','pending','published','ASSO-4 vague 1 : SIREN et RNA vérifiés à l''API officielle le 15/11/2026, descriptions rédigées par Guardiens, logo servi depuis le site de l''association.'),
('petits-freres-des-pauvres-lyon','Les Petits Frères des Pauvres (équipes de Lyon)','solidarite','Lyon','69001','69','{}'::text[],'Les Petits Frères des Pauvres luttent contre l''isolement des personnes âgées. À Lyon, l''équipe Presqu''Île et Nord, créée en 2015, intervient dans les 1er, 2e et 4e arrondissements et à Caluire : visites hebdomadaires à domicile ou en établissement (EHPAD, résidence autonomie, foyer), temps conviviaux comme la fête de Noël et les sorties, vie associative. D''autres équipes lyonnaises couvrent les 3e, 6e, 7e et 8e arrondissements. Fondée en 1946, l''association est reconnue d''utilité publique. Les bénévoles rendent visite une à deux heures par semaine, souvent en binôme, avec une formation assurée par l''association.',ARRAY['benevoles']::text[],'775680259','W751012234','Association reconnue d''utilité publique','https://www.petitsfreresdespauvres.fr/','https://www.facebook.com/lesPetitsFreresdesPauvres/','https://www.instagram.com/pfpauvres/',NULL,'https://www.petitsfreresdespauvres.fr/agir/donner-du-temps/devenir-benevole/','https://www.petitsfreresdespauvres.fr/nos-implantations/fraternite-regionale-auvergne-rhone-alpes/les-petits-freres-des-pauvres-de-lyon-nord/','https://www.petitsfreresdespauvres.fr/wp-content/uploads/2026/01/logo-pfp-80.svg','Visites régulières et temps conviviaux auprès de personnes âgées isolées, à Lyon et dans le Rhône.',1946,'[{"value": "42", "label": "bénévoles dans l''équipe Presqu''Île et Nord", "year": "", "source_url": "https://www.petitsfreresdespauvres.fr/nos-implantations/fraternite-regionale-auvergne-rhone-alpes/les-petits-freres-des-pauvres-de-lyon-nord/"}, {"value": "45", "label": "personnes accompagnées par cette équipe", "year": "", "source_url": "https://www.petitsfreresdespauvres.fr/nos-implantations/fraternite-regionale-auvergne-rhone-alpes/les-petits-freres-des-pauvres-de-lyon-nord/"}]'::jsonb,'[{"need": "benevoles", "detail": "Visites hebdomadaires à domicile ou en établissement, une à deux heures par semaine, avec une formation assurée par l''association. La candidature se fait depuis la page Devenir bénévole de son site.", "url": "https://www.petitsfreresdespauvres.fr/agir/donner-du-temps/devenir-benevole/"}]'::jsonb,'[{"fact": "SIREN 775 680 259, RNA W751012234, association reconnue d''utilité publique, siège national à Paris (vérifié à l''API officielle le 15/11/2026)", "url": "https://recherche-entreprises.api.gouv.fr/search?q=775680259"}, {"fact": "Équipe de Lyon Presqu''Île et Nord : activité, chiffres et page Devenir bénévole", "url": "https://www.petitsfreresdespauvres.fr/nos-implantations/fraternite-regionale-auvergne-rhone-alpes/les-petits-freres-des-pauvres-de-lyon-nord/"}]'::jsonb,NULL,'2026-11-15','pending','published','ASSO-4 vague 1 : SIREN et RNA vérifiés à l''API officielle le 15/11/2026, descriptions rédigées par Guardiens, logo servi depuis le site de l''association.')
